import { createDataRouter, defineRoute } from "@kasperrt/smolter/react";
import * as tasks from "./routes/tasks/route";
import * as task from "./routes/task/route";

export const router = createDataRouter([
  defineRoute("/tasks", tasks),
  defineRoute("/tasks/:id", task),
], { browser: true });

import { RouterProvider, Routes } from "@kasperrt/smolter/react";
import { router } from "./router";

export function App() {
  return <RouterProvider router={router}>
    <Routes fallback={<p>Page not found.</p>} />
  </RouterProvider>;
}
